def find_maximized_capital(k, w, profits, capital):
    done = [False] * len(profits)
    for _ in range(k):
        pick = -1
        for i in range(len(profits)):   # every round rescans every project
            if not done[i] and capital[i] <= w and (pick < 0 or profits[i] > profits[pick]):
                pick = i
        if pick < 0:
            break
        done[pick] = True
        w += profits[pick]
    return w

