from bisect import insort

class MedianFinder:
    def __init__(self):
        self.nums = []                 # always sorted

    def addNum(self, num):
        insort(self.nums, num)         # binary search, but the shift is O(n)

    def findMedian(self):
        n, mid = len(self.nums), len(self.nums) // 2
        return self.nums[mid] if n % 2 else (self.nums[mid - 1] + self.nums[mid]) / 2

