class MedianFinder:
    def __init__(self):
        self.count = [0] * 101         # follow-up: every value is in 0…100
        self.n = 0

    def addNum(self, num):
        self.count[num] += 1           # O(1)
        self.n += 1

    def findMedian(self):
        def kth(k):                    # value at sorted position k, 101 steps at most
            for v, c in enumerate(self.count):
                k -= c
                if k < 0:
                    return v
        mid = self.n // 2
        return kth(mid) if self.n % 2 else (kth(mid - 1) + kth(mid)) / 2
